interface Shape { public function area(): float; }
class Circle implements Shape { public function __construct(private float $r) {}
    public function area(): float { return M_PI * $this->r ** 2; } }
class Square implements Shape { public function __construct(private float $s) {}
    public function area(): float { return $this->s ** 2; } }
function total(Shape ...$s): float { return array_sum(array_map(fn($x)=>$x->area(), $s)); }

