class Bag {
    private array $data = [];
    public function __get($n) { return $this->data[$n] ?? null; }
    public function __set($n, $v) { $this->data[$n] = $v; }
    public function __isset($n) { return isset($this->data[$n]); }
}
$b = new Bag(); $b->foo = 42; echo $b->foo; // 42

class Api {
    public function __call($name, $args) {
        return "call $name(" . implode(',', $args) . ')';
    }
    public static function __callStatic($name, $args) {
        return "static $name";
    }
}
$a = new Api();
echo $a->doStuff(1, 2); // call doStuff(1,2)
echo Api::make();       // static make

class Multiplier {
    public function __construct(private int $k) {}
    public function __invoke(int $x): int { return $x * $this->k; }
    public function __toString(): string { return "x{$this->k}"; }
}
$double = new Multiplier(2);
echo $double(5);        // 10  (как функция)
echo "$double";         // x2  (как строка)
echo array_map($double, [1,2,3])[2]; // 6 (callable)

